package com.aoo.bcg.poker;
import com.aoo.bcg.gamespi.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class CpNineStageAcceptanceTest{
 @Test void sourceBackedNineStagesAndOldCommandShape(){CpGameProvider p=new CpGameProvider();CpSession s=(CpSession)p.roomFactory().create(new RoomCreationContext(39201,10,Map.of("moshi",1,"fanshushangxian",2,"difen",1))).requireAuthoritativeSession();StatePayload base=StatePayload.copyOf(s.authoritativeState());s.execute(c(1,1,20,"join",Map.of()));s.execute(c(2,2,30,"join",Map.of()));s.execute(c(3,1,20,"ready",Map.of()));s.execute(c(4,2,30,"ready",Map.of()));Map<String,Object>v=s.execute(c(5,0,10,"start",Map.of())).body().asMap();assertEquals(28,seat(v,0).get("cardCount"));int card=(Integer)((List<?>)seat(v,0).get("cards")).getFirst();s.execute(c(6,0,10,"operation",Map.of("opType",0,"cardType",2,"cardList",List.of(card),"substituteCard",List.of())));assertEquals(1,s.viewFor(20).get("currentSeat"));s.execute(c(7,1,20,"operation",Map.of("opType",1,"cardType",1,"cardList",List.of(),"substituteCard",List.of())));StatePayload replay=p.eventReplayProvider().orElseThrow().replay(base,s.events());assertEquals(s.authoritativeState(),replay.asMap());assertEquals(s.viewFor(20),p.restoreAuthoritativeSession(replay).orElseThrow().viewFor(20));assertThrows(IllegalArgumentException.class,()->p.eventReplayProvider().orElseThrow().replay(base,s.events().subList(1,3)));assertTrue(s.invariantViolations().isEmpty());assertEquals(84,CpRules.deck(false).size());}
 @Test void exactCardTypesSettlementSwitchesAndAtomicProvider(){assertEquals(CpRules.Type.FOUR,CpRules.classify(CpRules.Type.FOUR,List.of(2001,2002,2003,2004)).type());CpGameProvider p=new CpGameProvider();CpSession waiting=(CpSession)p.roomFactory().create(new RoomCreationContext(39202,10,Map.of("moshi",1,"fanshushangxian",2,"difen",1))).requireAuthoritativeSession();Map<String,Object>x=new LinkedHashMap<>(waiting.authoritativeState());x.put("players",Map.of(0,10L,1,20L,2,30L));x.put("ready",List.of(1,2));x.put("hands",Map.of(0,List.of(),1,List.of(201,202),2,List.of(301,302)));x.put("points",Map.of(0,2L,1,0L,2,0L));x.put("phase","FINISHED");x.put("current",0);x.put("leader",0);x.put("winner",0);x.put("passCount",0);x.put("lead",Map.of("type","FOUR","cards",List.of(2001,2002,2003,2004)));CpSession done=CpSession.restore(x);SettlementPayload result=done.settlement(1,CpGameProvider.VERSION);assertEquals(40L,result.scoreDelta().get(10L));assertEquals(-20L,result.scoreDelta().get(20L));assertEquals(0L,result.scoreDelta().values().stream().mapToLong(Long::longValue).sum());assertEquals(0,ServiceLoader.load(GameProvider.class).stream().filter(i->i.type()==CpGameProvider.class).count());}
 @SuppressWarnings("unchecked")private static Map<String,Object>seat(Map<String,Object>v,int s){return(Map<String,Object>)((Map<Integer,Object>)v.get("seats")).get(s);}private static GameCommandRequest c(long n,int seat,long player,String action,Map<String,Object>payload){return new GameCommandRequest("poker.cp.dispatch","cp"+n,n,39201,0,"1.0.0",String.valueOf(player),seat,Map.of("action",action,"payload",payload));}
}
